import sys
import shutil

def get_workflows_path() -> Path:
    """Retourne le chemin du répertoire `workflows` à côté de l'exécutable.
    - Si le dossier existe déjà, il est utilisé tel quel.
    - Sinon, il est créé et, si le binaire contient un répertoire `workflows`
      interne (ex. _MEIPASS), son contenu est copié pour fournir un jeu de départ.
    """
    # Chemin du répertoire contenant l'exécutable (ou le script en mode dev)
    if getattr(sys, "frozen", False):
        exe_dir = Path(sys.executable).parent
    else:
        exe_dir = Path(__file__).resolve().parent

    external = exe_dir / "workflows"
    if external.is_dir():
        return external

    # Crée le répertoire externe
    external.mkdir(parents=True, exist_ok=True)

    # Copie le contenu embarqué (si présent) dans le répertoire externe
    if getattr(sys, "frozen", False):
        internal = Path(sys._MEIPASS) / "workflows"
        if internal.is_dir():
            for item in internal.iterdir():
                dest = external / item.name
                if item.is_dir():
                    shutil.copytree(item, dest, dirs_exist_ok=True)
                else:
                    shutil.copy2(item, dest)
    return external
